function o(e){if(e===0)return"0 B";const r=1024,t=["B","KB","MB","GB","TB"],n=Math.floor(Math.log(e)/Math.log(r));return parseFloat((e/Math.pow(r,n)).toFixed(1))+" "+t[n]}function a(e){return e?new Date(e<1e12?e*1e3:e).toLocaleString("zh-CN"):"-"}function s(e){if(!e)return"-";const r=Math.floor(e);if(r<60)return r+"s";const t=Math.floor(r/60);return t<60?t+"m "+r%60+"s":Math.floor(t/60)+"h "+t%60+"m"}function c(e){switch(e){case"online":case"completed":return"success";case"busy":case"pending":case"assigned":return"primary";case"offline":case"failed":case"cancelled":case"error":return"danger";default:return"info"}}export{a,s as b,o as f,c as s};
